/bin/bash -lc "node --input-type=module - <<'NODE'
import { spawnSync } from 'node:child_process';

const executable = '/workspace/dataset/test10_executable';
const migrated = '/output/test10.mjs';

const cases = [
  ['--a', 'unicode测试', '--b', '-1000000', '--c', '2.71828'],
  ['--a', 'quotes\"inside', '--b', '0', '--c', '0.5'],
  ['--a', ' whitespace ', '--b', '777', '--c', '1.0'],
  ['--a', 'MixedCase', '--b', '-42', '--c', '-123.456'],
  ['--a', \"'single'\", '--b', '1', '--c', '1.0'],
  ['--a', 'line\\nbreak', '--b', '1', '--c', '1.0'],
  ['--a=-x', '--b=1_000', '--c=1_000.5'],
  ['--a', 'x', '--b', '1', '--c', '1e20'],
  ['--a', 'x', '--b', '1', '--c', '1e-5'],
  ['--a', 'x', '--b', '1', '--c', '-1.5'],
  ['--a', 'x', '--b', '-1', '--c', '-2.0'],
  ['-h'],
  ['--he'],
  [],
  ['--a', 'x', '--b', 'nope', '--c', '1.0'],
  ['--a', 'x', '--b', '1', '--c', 'nope'],
  ['--a', 'x', '--b', '1', '--c', '-1e-5'],
  ['--help=foo'],
  ['--a', 'x', '--b', '1', '--c', '1.0', '--extra', 'y'],
];

let failures = 0;

for (const args of cases) {
  const left = spawnSync(executable, args, { encoding: 'utf8' });
  const right = spawnSync('node', [migrated, ...args], { encoding: 'utf8' });

  const leftStdout = left.stdout;
  const rightStdout = right.stdout;
  const leftStderr = left.stderr.replaceAll('test10_executable', 'test10.mjs');
  const rightStderr = right.stderr;

  const same = left.status === right.status && leftStdout === rightStdout && leftStderr === rightStderr;
  if ("'!same) {
    failures += 1;
    console.log('"'FAIL', JSON.stringify(args));
    console.log('left status', left.status, 'right status', right.status);
    console.log('left stdout', JSON.stringify(leftStdout));
    console.log('right stdout', JSON.stringify(rightStdout));
    console.log('left stderr', JSON.stringify(leftStderr));
    console.log('right stderr', JSON.stringify(rightStderr));
  }
}

if (failures === 0) {
  console.log('All verification cases matched.');
  process.exit(0);
}

process.exit(1);
NODE"

