/bin/bash -lc "node --input-type=module - <<'NODE'
import { spawnSync } from 'node:child_process';

const executable = '/workspace/dataset/test10_executable';
const migrated = '/output/test10.mjs';
const floatCases = [
  '0', '1', '1.0', '1.00', '+5', '010', '0.0001', '0.00009', '0.00001', '1e-5', '1e-6',
  '1000000', '1000000000000000', '10000000000000000', '9999999999999999', '1e20', '1e21',
  '-0.0', '-1.5', '-.5', '-0.5', '123.4500', '1.23456789012345678', '1_000.5', '.5', '1.',
  '1.23e15', '1.23e16', '9e-05', '1e-09', '1e-10'
];
let failures = 0;
for (const f of floatCases) {
  const args = ['--a', 'x', '--b', '1', '--c', f];
  const left = spawnSync(executable, args, { encoding: 'utf8' });
  const right = spawnSync('node', [migrated, ...args], { encoding: 'utf8' });
  if (left.status "'!== right.status || left.stdout !== right.stdout || left.stderr.replaceAll('"'test10_executable', 'test10.mjs') "'!== right.stderr) {
    failures += 1;
    console.log('"'FAIL', f);
    console.log('left', left.status, JSON.stringify(left.stdout), JSON.stringify(left.stderr));
    console.log('right', right.status, JSON.stringify(right.stdout), JSON.stringify(right.stderr));
  }
}
if (failures === 0) {
  console.log('Float verification matched.');
}
process.exit(failures === 0 ? 0 : 1);
NODE"

